import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_sigmoid_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Vectorized sigmoid kernel operating on float4 chunks using a grid-stride loop
// for better occupancy/coalescing across arbitrarily large tensors.
// This version manually unrolls the loop by a factor of 2, issuing two
// independent float4 loads per iteration before consuming either of them.
// This increases memory-level parallelism (more outstanding load/store
// transactions in flight), which helps better saturate DRAM bandwidth on
// a kernel that is already heavily memory-bandwidth bound (~91% DRAM
// throughput), without materially increasing register pressure since only
// two float4 temporaries are live at once.
__global__ void sigmoid_kernel_vec4(const float4* __restrict__ X4,
                                     float4* __restrict__ Y4,
                                     int64_t N4)
{
  int64_t tid = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;
  int64_t idx = tid;
  // Main loop: process two float4 vectors per iteration to increase
  // memory-level parallelism while keeping the grid-stride structure.
  for (; idx + stride < N4; idx += 2 * stride) {
    float4 v0 = __ldcs(&X4[idx]);
    float4 v1 = __ldcs(&X4[idx + stride]);
    v0.x = 1.0f / (1.0f + __expf(-v0.x));
    v0.y = 1.0f / (1.0f + __expf(-v0.y));
    v0.z = 1.0f / (1.0f + __expf(-v0.z));
    v0.w = 1.0f / (1.0f + __expf(-v0.w));
    v1.x = 1.0f / (1.0f + __expf(-v1.x));
    v1.y = 1.0f / (1.0f + __expf(-v1.y));
    v1.z = 1.0f / (1.0f + __expf(-v1.z));
    v1.w = 1.0f / (1.0f + __expf(-v1.w));
    __stcs(&Y4[idx], v0);
    __stcs(&Y4[idx + stride], v1);
  }
  // Tail loop: handles the remaining single vector(s) that don't fit the
  // unroll-by-2 pattern.
  for (; idx < N4; idx += stride) {
    float4 v = __ldcs(&X4[idx]);
    v.x = 1.0f / (1.0f + __expf(-v.x));
    v.y = 1.0f / (1.0f + __expf(-v.y));
    v.z = 1.0f / (1.0f + __expf(-v.z));
    v.w = 1.0f / (1.0f + __expf(-v.w));
    __stcs(&Y4[idx], v);
  }
}
// Scalar fallback kernel for any leftover elements (N % 4 != 0), also using
// a grid-stride loop for robust tail handling.
__global__ void sigmoid_kernel_scalar(const float* __restrict__ X,
                                       float* __restrict__ Y,
                                       int64_t Nrem)
{
  int64_t tid = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;
  for (int64_t idx = tid; idx < Nrem; idx += stride) {
    float v = __ldcs(&X[idx]);
    __stcs(&Y[idx], 1.0f / (1.0f + __expf(-v)));
  }
}
torch::Tensor cute_sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);
  int64_t N = x_c.numel();
  int64_t N4 = N / 4;
  int64_t rem = N - N4 * 4;
  const float* xptr = x_c.data_ptr<float>();
  float* yptr = y.data_ptr<float>();
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  constexpr int Threads = 256;
  constexpr int64_t MaxBlocks = 65536; // cap grid size, rely on grid-stride loop
  if (N4 > 0) {
    int64_t desired_blocks = (N4 + Threads - 1) / Threads;
    int64_t blocks = desired_blocks < MaxBlocks ? desired_blocks : MaxBlocks;
    const float4* xptr4 = reinterpret_cast<const float4*>(xptr);
    float4* yptr4 = reinterpret_cast<float4*>(yptr);
    sigmoid_kernel_vec4<<<(unsigned)blocks, Threads, 0, stream>>>(xptr4, yptr4, N4);
  }
  if (rem > 0) {
    int64_t offset = N4 * 4;
    int64_t desired_blocks = (rem + Threads - 1) / Threads;
    int64_t blocks = desired_blocks < MaxBlocks ? desired_blocks : MaxBlocks;
    sigmoid_kernel_scalar<<<(unsigned)blocks, Threads, 0, stream>>>(
        xptr + offset, yptr + offset, rem);
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "cute_sigmoid_forward launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

cute_sigmoid_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_sigmoid_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Sigmoid activation using a custom CUTE kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_sigmoid_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_sigmoid_forward(x)

